const $=s=>document.querySelector(s);const photo=(id,w=700)=>`assets/${id}.jpg`;
const categories=[['Nannies','♡','Care for your little ones'],['Cleaning','✧','A fresh start for your space'],['Mechanics','⚒','Keep your world moving'],['Hair & beauty','✂','Look good. Feel great.'],['Skilled hands','⌂','The right hands for the job']];
const profiles=[{id:1,name:'Amara Okafor',category:'Nannies',title:'Thoughtful care for your little ones',location:'Abuja',area:'Maitama',price:8000,unit:'day',image:'photo-1544717305-2782549b5136',skills:['Childcare','After-school care','Meal preparation'],about:'A patient and attentive childcare professional who enjoys creating playful routines, helping with homework, and making children feel at home.'},{id:2,name:'Sparkle & Shine',category:'Cleaning',title:'A cleaner home. A calmer you.',location:'Abuja',area:'Gwarinpa',price:15000,unit:'visit',image:'photo-1581578731548-c64695cc6952',skills:['Deep cleaning','Home cleaning','Move-in cleaning'],about:'A detail-focused cleaning team that helps busy households enjoy their space. Explore services for one-off deep cleans and regular home care.'},{id:3,name:'Tunde Auto Care',category:'Mechanics',title:'Expert hands for a smoother ride',location:'Abuja',area:'Wuse',price:10000,unit:'service',image:'photo-1486262715619-67b85e0b08d3',skills:['Vehicle diagnostics','Routine maintenance','Oil changes'],about:'Practical vehicle care with clear explanations. Discuss your car, its symptoms, and the service you need before agreeing on a quote.'},{id:4,name:'The Hair Room',category:'Hair & beauty',title:'Your next look, beautifully made',location:'Abuja',area:'Garki',price:12000,unit:'session',image:'photo-1562322140-8baeececf3df',skills:['Hair styling','Braids','Hair care'],about:'From a fresh everyday look to a special occasion, discover a thoughtful approach to styling and personal hair care.'},{id:5,name:'Daniel Woodworks',category:'Skilled hands',title:'Careful craftsmanship for your home',location:'Abuja',area:'Jabi',price:20000,unit:'job',image:'photo-1504148455328-c376907d081c',skills:['Carpentry','Furniture repair','Assembly'],about:'Helping your home work better with furniture assembly, practical repairs, and made-to-fit carpentry.'}];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};const persist=(key,val)=>{try{localStorage.setItem(key,JSON.stringify(val))}catch{toast('Your browser could not save this change.')}};let saved=read('fyield-saved',[]);saved=Array.isArray(saved)?saved.filter(id=>Number.isInteger(id)&&profiles.some(p=>p.id===id)):[];let drafts=[],selected='All services',savedOnly=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function choose(cat){selected=cat;savedOnly=false;$('#query').value='';render();$('#providers').scrollIntoView({behavior:'smooth',block:'center'})}
function render(){const items=[...profiles,...drafts];$('#savedCount').textContent=saved.length;$('#savedBtn').setAttribute('aria-pressed',savedOnly);$('#categories').innerHTML=categories.map(([cat,icon,desc])=>`<button class="cat ${selected===cat?'selected':''}" data-cat="${cat}" aria-pressed="${selected===cat}"><span class="cat-icon" aria-hidden="true">${icon}</span><h3>${cat}<span>↗</span></h3><p>${desc}</p></button>`).join('');$('#chips').innerHTML=['All services',...categories.map(c=>c[0])].map(c=>`<button class="chip ${c===selected?'selected':''}" data-cat="${c}" aria-pressed="${c===selected}">${c}</button>`).join('');const q=$('#query').value.toLowerCase().trim(),loc=$('#location').value;let shown=items.filter(p=>(selected==='All services'||p.category===selected)&&(!savedOnly||saved.includes(p.id))&&(!loc||p.area===loc)&&(!q||[p.name,p.category,p.title,p.location,p.area,...p.skills].join(' ').toLowerCase().includes(q)));if($('#sort').value==='low')shown.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')shown.sort((a,b)=>b.price-a.price);$('#resultsTitle').textContent=savedOnly?'Your saved professionals.':selected!=='All services'?`${selected}, with a human touch.`:'Good people. Ready to help.';$('#providers').innerHTML=shown.map(p=>`<article class="provider"><div class="card-img"><img src="${photo(p.image)}" alt="${esc(p.category)} service illustration" loading="lazy"><button class="save ${saved.includes(p.id)?'is-saved':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><span class="card-type">${esc(p.category)}</span></div><div class="card-body"><button class="provider-title" data-profile="${p.id}">${esc(p.name)} ↗</button><p>${esc(p.title)}</p><div class="card-meta">⌖ ${esc(p.area)}, ${esc(p.location)}</div><div class="card-bottom"><span>From <b>₦${Number(p.price).toLocaleString()}</b> / ${esc(p.unit)}</span><button class="arrow" data-profile="${p.id}" aria-label="View ${esc(p.name)}">↗</button></div></div></article>`).join('');$('#empty').hidden=shown.length>0;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>choose(b.dataset.cat));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(i=>i!==id):[...saved,id];persist('fyield-saved',saved);render()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profile(Number(b.dataset.profile)))}
function profile(id){const p=[...profiles,...drafts].find(p=>p.id===id);openModal(`<img class="profile-image" src="${photo(p.image)}" alt="${esc(p.category)} service illustration"><h2>${esc(p.name)}</h2><p>⌖ ${esc(p.area)}, ${esc(p.location)} · ${esc(p.category)}</p><p>${esc(p.about)}</p><div>${p.skills.map(s=>`<span class="badge">${esc(s)}</span>`).join('')}</div><p>Starting from <strong>₦${Number(p.price).toLocaleString()} / ${esc(p.unit)}</strong></p><p class="notice">${p.draft?'Your local listing draft.':'Illustrative profile with sample pricing and portfolio imagery.'} Contact and booking are not live yet.</p><div class="modal-actions"><button class="btn dark" id="requestBtn">Contact availability ↗</button></div>`);$('#requestBtn').onclick=()=>enquiry(p)}
function enquiry(p){openModal(`<div class="eyebrow">ABUJA LAUNCH PREVIEW</div><h2>Real connections, coming next.</h2><p>${esc(p.name)} is an illustrative profile. Enquiries and bookings are not available in this preview.</p><p class="notice">We are not collecting names, addresses, phone numbers, childcare information, or job descriptions here. Provider contact will open after accounts and protected messaging are ready.</p><button class="btn dark" id="done">Keep exploring →</button>`);$('#done').onclick=()=>$('#modal').close()}
function listing(){openModal(`<div class="eyebrow">FOR ABUJA’S ENTREPRENEURS</div><h2>Your skill deserves a spotlight.</h2><p>We’re preparing a home for Abuja’s nannies, cleaners, mechanics, hairdressers, and skilled tradespeople.</p><div class="onboarding-steps"><article><b>01 · Build your profile</b><p>Describe your skills, service areas, and availability.</p></article><article><b>02 · Show your work</b><p>Add work you have permission to share, without exposing client or child details.</p></article><article><b>03 · Connect with customers</b><p>Discuss the work privately before agreeing on a booking.</p></article></div><p class="notice">Provider registration is not open yet. No personal details are requested or stored by this screen.</p><button class="btn dark" id="done">Explore the preview →</button>`);$('#done').onclick=()=>$('#modal').close()}
function privacy(){openModal(`<div class="eyebrow">CLEAR FROM THE START</div><h2>Your data in this preview.</h2><p>This release is a design preview, not an operating booking platform. Profiles, portfolio photographs, and prices are illustrative.</p><h3>What stays on your device</h3><p>Saved favorites contain only sample profile IDs. Search and filters remain in the page. We do not collect enquiry details, account details, payments, or identity documents.</p><h3>Hosting and imagery</h3><p>Hosting providers may process ordinary connection information such as IP addresses to deliver the site. This version includes no analytics or advertising trackers.</p><h3>Earlier prototype drafts</h3><p>If you used an earlier preview on this same address, you can remove its saved enquiries, listings, and favorites below. Data on another address or file must be cleared there.</p><button class="btn outline" id="clearData">Clear this preview’s saved data</button>`);$('#clearData').onclick=()=>{try{['fyield-saved','fyield-listings','fyield-enquiries'].forEach(k=>localStorage.removeItem(k));saved=[];render();toast('Preview data cleared from this address.')}catch{toast('Storage is unavailable. Clear site data in your browser settings.')}}}
$('#privacyBtn').onclick=privacy;
$('#searchForm').onsubmit=e=>{e.preventDefault();selected='All services';savedOnly=false;render();$('#providers').scrollIntoView({behavior:'smooth',block:'start'})};$('#sort').onchange=render;$('#location').onchange=render;$('#savedBtn').onclick=()=>{savedOnly=!savedOnly;selected='All services';$('#query').value='';$('#location').value='';render();$('#providers').scrollIntoView({behavior:'smooth'})};function reset(){selected='All services';savedOnly=false;$('#query').value='';$('#location').value='';render();$('#providers').scrollIntoView({behavior:'smooth',block:'center'})}$('#reset').onclick=reset;$('#allServices').onclick=reset;document.querySelectorAll('[data-list]').forEach(b=>b.onclick=listing);document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{selected='All services';savedOnly=false;$('#query').value=b.dataset.query;render();$('#providers').scrollIntoView({behavior:'smooth'})});const works=[{id:4,title:'A fresh look, a little more confidence',sub:'Hair & beauty · The Hair Room',image:'photo-1521590832167-7bcbfaa6381f'},{id:2,title:'Making room for a fresh start',sub:'Home cleaning · Sparkle & Shine',image:'photo-1600210492486-724fe5c67fb0'},{id:5,title:'Built with care. Made to last.',sub:'Skilled hands · Daniel Woodworks',image:'photo-1504148455328-c376907d081c'}];$('#workGrid').innerHTML=works.map(w=>`<button class="work-card" data-work="${w.id}"><div class="work-photo"><img src="${photo(w.image)}" alt="${esc(w.title)} — illustrative portfolio photo" loading="lazy"></div><h3>${w.title} ↗</h3><p>${w.sub}</p></button>`).join('');document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>profile(Number(b.dataset.work)));render();
